package cl.duoc.dsy1107.notificationservice.service;
import cl.duoc.dsy1107.notificationservice.dto.NotificationMessage; import cl.duoc.dsy1107.notificationservice.entity.NotifyLog; import cl.duoc.dsy1107.notificationservice.repository.NotifyLogRepository; import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Service;
@Service public class NotificationConsumer { private final NotifyLogRepository repo; private final ObjectMapper mapper; public NotificationConsumer(NotifyLogRepository r,ObjectMapper m){repo=r;mapper=m;} @RabbitListener(queues="${app.rabbitmq.queue}") public void consume(NotificationMessage message) throws JsonProcessingException { NotifyLog n=new NotifyLog(); n.setOtId(message.otId()); n.setClienteId(message.clienteId()); n.setCanal(message.canal()); n.setPayloadJson(mapper.writeValueAsString(message)); repo.save(n); } }
